CREATE TABLE IF NOT EXISTS sightings (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,species TEXT NOT NULL,scientific_name TEXT,category TEXT,description TEXT,photo_key TEXT,latitude REAL,longitude REAL,confidence REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_sightings_user ON sightings(user_id);CREATE INDEX IF NOT EXISTS idx_sightings_species ON sightings(user_id,scientific_name);